import { gsap } from 'gsap';
import {
  MeshPhysicalNodeMaterial,
  MeshStandardNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import { uv, texture, positionLocal, normalLocal, mix, color, float } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Shape, ExtrudeGeometry, PlaneGeometry, CircleGeometry, Mesh, Texture,
    DirectionalLight, PointLight, DoubleSide } = THREE;

  const colors = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10',
  };

  const group = new Group();
  group.name = 'home-quote-panel';

  const panelW = 3.2;
  const panelH = 1.8;
  const bevel = 0.05;

  // ---------- extruded machined-metal frame ----------
  const shape = new Shape();
  const r = 0.12;
  const hw = panelW / 2;
  const hh = panelH / 2;
  shape.moveTo(-hw + r, -hh);
  shape.lineTo(hw - r, -hh);
  shape.quadraticCurveTo(hw, -hh, hw, -hh + r);
  shape.lineTo(hw, hh - r);
  shape.quadraticCurveTo(hw, hh, hw - r, hh);
  shape.lineTo(-hw + r, hh);
  shape.quadraticCurveTo(-hw, hh, -hw, hh - r);
  shape.lineTo(-hw, -hh + r);
  shape.quadraticCurveTo(-hw, -hh, -hw + r, -hh);

  const frameGeo = new ExtrudeGeometry(shape, {
    depth: 0.1,
    bevelEnabled: true,
    bevelThickness: bevel,
    bevelSize: bevel,
    bevelSegments: 3,
    curveSegments: 8,
  });
  frameGeo.center();

  const frameMat = new MeshPhysicalNodeMaterial({
    color: colors.ink,
    metalness: 0.5,
    roughness: 0.55,
    clearcoat: 0.2,
    clearcoatRoughness: 0.3,
  });
  const frame = new Mesh(frameGeo, frameMat);
  frame.position.z = -0.06;
  group.add(frame);

  // ---------- tessellated parallax-displacement inset plane ----------
  const insetW = panelW - 0.28;
  const insetH = panelH - 0.28;
  const planeGeo = new PlaneGeometry(insetW, insetH, 64, 64);

  const displacementScale = float(0.06);
  const fallbackGradient = mix(color(colors.ink), color(colors.paper), uv().y);

  const planeMat = new MeshStandardNodeMaterial({
    roughness: 0.6,
    metalness: 0.2,
  });
  planeMat.colorNode = fallbackGradient;

  const plane = new Mesh(planeGeo, planeMat);
  plane.position.z = 0.02;
  group.add(plane);

  let loadedColorTex = null;
  let loadedDepthTex = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedColorTex = tex;
      planeMat.colorNode = texture(tex, uv());
      planeMat.needsUpdate = true;
    }).catch(() => {});
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      loadedDepthTex = tex;
      const disp = texture(tex, uv()).r.sub(0.5).mul(displacementScale);
      planeMat.positionNode = positionLocal.add(normalLocal.mul(disp));
      planeMat.needsUpdate = true;
    }).catch(() => {});
  }

  // ---------- accent rim light ----------
  const rimLight = new DirectionalLight(colors.accent, 0.9);
  rimLight.position.set(-1.2, 0.6, 1.4);
  group.add(rimLight);

  const fillPoint = new PointLight(colors.accent, 0.4, 4);
  fillPoint.position.set(1.0, -0.4, 0.8);
  group.add(fillPoint);

  // ---------- contact shadow ----------
  const shadowGeo = new CircleGeometry(Math.max(panelW, panelH) * 0.62, 32);
  const shadowMat = new MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.45,
    side: DoubleSide,
  });
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -hh - 0.35, -0.04);
  group.add(shadow);

  // ---------- optional text (bridging idiom, verbatim only) ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textNodes = [];
  let yCursor = 0.35;
  for (const item of items) {
    const isAttribution = item.role && /attribution|caption|author/i.test(item.role);
    const t = ctx.fontAtlas.createText(item.text, {
      fontSize: isAttribution ? 24 : 34,
      color: isAttribution ? colors.accent : colors.paper,
      align: 'left',
      maxWidthPx: 460,
    });
    t.position.set(-hw + 0.3, yCursor, 0.09);
    t.scale.setScalar(0.0042);
    group.add(t);
    textNodes.push(t);
    yCursor -= isAttribution ? 0.3 : 0.42;
  }

  // ---------- cinematic primitives ----------
  const primitiveHandles = [];
  const specPrimitives = config.cinematicPrimitives ?? [];
  for (const prim of specPrimitives) {
    const fn = ctx.primitives?.[prim.name];
    if (!fn) continue;
    const target = prim.name === 'depth-rotate' ? group : plane;
    const handle = fn(target, { ...(prim.params ?? {}), trigger: prim.trigger });
    primitiveHandles.push(handle);
  }

  // ---------- interaction handlers ----------
  const timelines = [];
  const baseY = group.position.y;

  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(group.position, {
    y: '+=0.15',
    duration: 0.5,
    ease: 'power3.out',
  });
  timelines.push(hoverTl);

  group.userData.handlers = {
    hover: (isHovering) => {
      if (isHovering) hoverTl.play();
      else hoverTl.reverse();
    },
    click: () => {
      const pressTl = gsap.timeline();
      pressTl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' })
        .to(group.scale, { x: 1, y: 1, z: 1, duration: 0.2, ease: 'power2.out' });
      timelines.push(pressTl);
      ctx.emit('hub-home.select', { nodeId: config.id ?? 'home-quote' });
    },
  };

  // ---------- entrance: weighted-settle ----------
  group.scale.set(0.96, 0.96, 0.96);
  const entranceTl = gsap.timeline();
  entranceTl.to(group.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'power4.out',
  });
  timelines.push(entranceTl);

  // ---------- cleanup ----------
  group.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const h of primitiveHandles) {
      try { h?.cleanup?.(); } catch (e) {}
    }
    frameGeo.dispose();
    frameMat.dispose();
    planeGeo.dispose();
    planeMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    if (loadedColorTex) loadedColorTex.dispose();
    if (loadedDepthTex) loadedDepthTex.dispose();
    for (const t of textNodes) {
      t.traverse?.((child) => {
        child.geometry?.dispose?.();
        child.material?.dispose?.();
      });
    }
  };

  return group;
}
